            elif (j==c0-1 or j==c1+1) and r0<=i<=r1 and all(g[k][j]==c or (k,j) in noise for k in range(r0,r1+1)): ok=True
            if ok: cands[c]=max(cands.get(c,0),(r1-r0+1)*(c1-c0+1))
        if cands:
            out[i][j]=max(cands,key=cands.get)
        elif bg in nb.values():
            out[i][j]=bg
        else:
            out[i][j]=collections.Counter(nb.values()).most_common(1)[0][0]
    return out
